"""Procedural textures for floors and objects (numpy only, generated by this script: no third-party
images, no licence questions). Each kind is drawn with a seeded generator, so a texture pool is
reproducible from (seed, index).

    img = make_texture(np.random.default_rng(3), "tape_markings", 512)   # HxWx3 uint8
"""

from __future__ import annotations

import numpy as np

KINDS = ("noise", "checker", "stripes", "grid", "tape_markings", "wood", "speckle", "concrete", "blue_grid", "plain")


def _rand_colour(rng: np.random.Generator, dark: bool = False) -> np.ndarray:
    c = rng.uniform(0, 1, 3)
    return (c * (0.4 if dark else 1.0) * 255).astype(np.float32)


def _smooth_noise(rng: np.random.Generator, size: int, cells: int) -> np.ndarray:
    """Value noise in [0, 1]: random grid upsampled bilinearly."""
    g = rng.uniform(0, 1, (cells + 1, cells + 1))
    x = np.linspace(0, cells, size, endpoint=False)
    i = x.astype(int)
    f = x - i
    a = g[i][:, i] * (1 - f)[None, :] + g[i][:, i + 1] * f[None, :]
    b = g[i + 1][:, i] * (1 - f)[None, :] + g[i + 1][:, i + 1] * f[None, :]
    return a * (1 - f)[:, None] + b * f[:, None]


def make_texture(rng: np.random.Generator, kind: str, size: int = 512) -> np.ndarray:
    yy, xx = np.mgrid[0:size, 0:size]
    c1, c2 = _rand_colour(rng), _rand_colour(rng)
    if kind == "plain":
        img = np.broadcast_to(c1, (size, size, 3)).copy()
    elif kind == "noise":
        n = sum(_smooth_noise(rng, size, int(c)) * w for c, w in ((4, 0.5), (16, 0.3), (64, 0.2)))
        img = c1 * n[..., None] + c2 * (1 - n[..., None])
    elif kind == "checker":
        k = int(rng.integers(4, 24))
        mask = ((xx * k // size) + (yy * k // size)) % 2
        img = np.where(mask[..., None] == 1, c1, c2)
    elif kind == "stripes":
        k, a = rng.uniform(4, 30), rng.uniform(0, np.pi)
        mask = (np.sin((xx * np.cos(a) + yy * np.sin(a)) / size * 2 * np.pi * k) > rng.uniform(-0.5, 0.5))
        img = np.where(mask[..., None], c1, c2)
    elif kind in ("grid", "blue_grid"):
        if kind == "blue_grid":  # like the evaluation scene's floor (light blue tiles, white lines), randomised
            c2 = np.array([120, 170, 210], np.float32) * rng.uniform(0.8, 1.15, 3)
            c1 = np.array([245, 245, 245], np.float32)
        k, w = int(rng.integers(3, 12)), rng.uniform(0.01, 0.04)
        fx, fy = (xx * k / size) % 1, (yy * k / size) % 1
        mask = (fx < w) | (fy < w)
        img = np.where(mask[..., None], c1, c2)
    elif kind == "tape_markings":  # floor with painted lines / tape, like a lab or workshop
        img = np.broadcast_to(_rand_colour(rng, dark=rng.random() < 0.5), (size, size, 3)).copy()
        for _ in range(int(rng.integers(2, 7))):
            colour = np.array([[240, 200, 30], [240, 240, 240], [220, 40, 40], [30, 30, 30]][rng.integers(4)], np.float32)
            w, pos = int(rng.integers(6, 30)), int(rng.integers(0, size))
            if rng.random() < 0.5:
                img[:, pos:pos + w] = colour
            else:
                img[pos:pos + w, :] = colour
    elif kind == "wood":
        n = _smooth_noise(rng, size, 6)
        rings = np.sin((yy / size * rng.uniform(20, 60) + n * 10) * 2 * np.pi) * 0.5 + 0.5
        base = np.array([150, 100, 55], np.float32) * rng.uniform(0.6, 1.3, 3)
        img = base * (0.75 + 0.25 * rings[..., None])
    elif kind == "speckle":
        img = np.broadcast_to(c1, (size, size, 3)).copy()
        m = rng.random((size, size)) < rng.uniform(0.02, 0.2)
        img[m] = c2
    elif kind == "concrete":
        n = sum(_smooth_noise(rng, size, int(c)) * w for c, w in ((8, 0.4), (64, 0.4), (256, 0.2)))
        g = rng.uniform(90, 200)
        img = np.repeat((g * (0.75 + 0.5 * n))[..., None], 3, axis=2)
    else:
        raise ValueError(kind)
    return np.clip(img, 0, 255).astype(np.uint8)
